{"code":"import json, glob, os, math
from collections import Counter, defaultdict
vals=[]; A=Counter(); gate_counter=defaultdict(Counter); avail_counts=[]; W_counts=Counter(); unavailable=Counter(); pass_false=0; total_sk=0; trist=Counter()
for f in glob.glob('bench/logs/*/runner_state.json'):
    if os.path.getsize(f)>60_000_000: continue
    try: data=json.load(open(f, errors='ignore'))
    except Exception: continue
    def walk(o):
        global pass_false,total_sk
        if isinstance(o,dict):
            sk=o.get('sk_result')
            if isinstance(sk,dict) and 'tristate' in sk:
                trist[str(sk.get('tristate'))]+=1
                if sk.get('tristate')=='ADMISSIBLE':
                    vals.append(sk.get('sk'))
                    A[sk.get('A')]+=1
                    gd=sk.get('gate_details') or {}
                    W=0; n_av=0
                    for name, wt in [('e2_regression',2),('e3_ruff',1),('e4_bandit',2)]:
                        d=gd.get(name) or {}
                        score=d.get('score')
                        if isinstance(score,(int,float)) and not isinstance(score,bool):
                            gate_counter[name][score]+=1; W+=wt; n_av+=1
                        else:
                            unavailable[name]+=1
                    avail_counts.append(n_av); W_counts[W]+=1
                    if sk.get('passes_threshold') is False: pass_false+=1
            for v in o.values(): walk(v)
        elif isinstance(o,list):
            for v in o: walk(v)
    walk(data)
print('trist', trist)
print('admissible',len(vals),'eq1',sum(v==1.0 for v in vals),'min',min(vals),'unique',len(set(vals)),'pass_false',pass_false)
print('A',A)
print('avail_counts',Counter(avail_counts),'W',W_counts,'unavailable',unavailable)
for name,c in gate_counter.items():
    print(name,'distinct',len(c),'total',sum(c.values()),'eq1',c[1.0],'top',c.most_common(5))
# effective levels
cnt=Counter(vals); n=len(vals)
H=-sum((k/n)*math.log2(k/n) for k in cnt.values())
mean=sum(vals)/n
sd=(sum((x-mean)**2 for x in vals)/n)**0.5
print('H',H,'eff',2**H,'sd',sd)
# Wilson 121? e2 unavailable and eq1 counts
def wilson(k,n):
    z=1.959963984540054; p=k/n; d=1+z*z/n; c=p+z*z/(2*n); h=z*math.sqrt(p*(1-p)/n+z*z/(4*n*n)); return (p,(c-h)/d,(c+h)/d)
print('eq1 wilson',wilson(sum(v==1.0 for v in vals),len(vals)))
